Approach 1: PostgreSQL Schema Isolation
This approach uses individual schemas for each tenant, which provides strong isolation and allows for schema-level permissions.

-- Create a shared database
CREATE DATABASE multi_tenant_db;

-- Initialization function to provision a new tenant
CREATE OR REPLACE PROCEDURE create_tenant(tenant_name TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    -- Create schema for the tenant
    EXECUTE 'CREATE SCHEMA tenant_' || tenant_name;

    -- Create a role for the tenant to own their schema
    EXECUTE 'CREATE ROLE role_' || tenant_name || ' NOLOGIN';

    -- Grant usage and permissions to the tenant role
    EXECUTE 'GRANT USAGE ON SCHEMA tenant_' || tenant_name || ' TO role_' || tenant_name;
    EXECUTE 'GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA tenant_' || tenant_name || ' TO role_' || tenant_name;
END;
$$;

